<section x-show="activeTab==='vouchers'" x-cloak><h2>Your vouchers</h2><div class="uv-voucher-tabs">@foreach(['eligible'=>'Available','used'=>'Used','expired'=>'Unavailable'] as $key=>$label)<button @click="voucherSubTab='{{ $key }}'" :aria-pressed="voucherSubTab==='{{ $key }}'">{{ $label }} ({{ $voucherGroups['counts'][$key] }})</button>@endforeach</div>@if($couponStatus)<p role="status">{{ $couponStatus['message'] }}</p>@endif
<div class="uv-voucher-grid">@foreach($vouchers as $voucher)<article class="uv-voucher-card" x-show="voucherSubTab===@js($voucher['status'])"><span class="uv-perforation" aria-hidden="true"></span><div class="uv-voucher-value"><i data-lucide="ticket"></i>{{ $voucher['discountDisplay']??$voucher['title'] }}<small>OFF</small></div><div class="uv-voucher-copy"><h3>{{ $voucher['title'] }}</h3><p>{{ $voucher['description'] }}</p><p><strong class="uv-voucher-code" x-data="{copyStatus:''}">{{ $voucher['code'] }}<button type="button" aria-label="Copy voucher code" @click="navigator.clipboard.writeText(@js($voucher['code'])).then(()=>copyStatus='Copied').catch(()=>copyStatus='Copy failed')"><i data-lucide="copy" aria-hidden="true"></i></button><span role="status" x-text="copyStatus"></span></strong></p><p>{{ $voucher['minSpendDisplay'] }}</p>@if(!empty($voucher['categoryRestriction']))<p>{{ $voucher['categoryRestriction'] }}</p>@endif @if($voucher['status']==='eligible')<button class="uv-primary" @disabled($preview) @click="applyVoucher(@js($voucher['code']))">Use voucher</button>@endif<details><summary>Terms &amp; conditions<i data-lucide="chevron-down"></i></summary><p>{{ $voucher['description'] }}</p><p>{{ $voucher['minSpendDisplay'] }}</p>@if(!empty($voucher['categoryRestriction']))<p>{{ $voucher['categoryRestriction'] }}</p>@endif</details></div></article>@endforeach</div>
@foreach(['eligible','used','expired'] as $key)@if($voucherGroups['counts'][$key]===0)<p x-show="voucherSubTab==='{{ $key }}'" class="uv-empty">No vouchers in this category.</p>@endif@endforeach
<form class="uv-manual-voucher" @submit.prevent="applyVoucher(couponInput)"><label for="universal-voucher-code">Have a voucher code?</label><input id="universal-voucher-code" x-model="couponInput" placeholder="Enter voucher code" required @disabled($preview)><button class="uv-primary" @disabled($preview)>Apply</button></form></section>
